-- Local/remote D1 migration only; applying this file never copies or exposes R2 media.
PRAGMA foreign_keys = ON;
CREATE TABLE event_media (
  media_id TEXT PRIMARY KEY REFERENCES media_assets(id),
  width INTEGER NOT NULL CHECK(width>0),
  height INTEGER NOT NULL CHECK(height>0),
  source TEXT,
  key_id TEXT,
  storage TEXT NOT NULL DEFAULT 'private' CHECK(storage='private'),
  verified_at TEXT
);
CREATE TABLE event_details (
  content_id TEXT PRIMARY KEY REFERENCES content_entries(id),
  starts_at TEXT,
  ends_at TEXT,
  event_date TEXT NOT NULL,
  timezone TEXT NOT NULL DEFAULT 'Asia/Bangkok' CHECK(timezone='Asia/Bangkok'),
  time_precision TEXT NOT NULL DEFAULT 'exact' CHECK(time_precision IN ('exact','backfill_placeholder')),
  location TEXT NOT NULL DEFAULT '',
  category TEXT NOT NULL,
  initiator TEXT NOT NULL,
  series_name TEXT,
  series_issue INTEGER CHECK(series_issue IS NULL OR series_issue>0),
  poster_media_id TEXT NOT NULL UNIQUE REFERENCES event_media(media_id),
  poster_alt TEXT NOT NULL,
  detail_url TEXT,
  registration_url TEXT,
  source_published_at TEXT,
  version INTEGER NOT NULL DEFAULT 1 CHECK(version>0),
  CHECK((time_precision='exact' AND starts_at IS NOT NULL AND ends_at IS NOT NULL AND julianday(ends_at)>julianday(starts_at)) OR
    (time_precision='backfill_placeholder' AND starts_at IS NULL AND ends_at IS NULL AND event_date='2026-07-10' AND
    content_id IN ('cmi-ai-3d-school-workshop-01-montfort','cmi-ai-3d-school-workshop-02-montfort')))
);
CREATE INDEX event_details_date_idx ON event_details(event_date DESC);
CREATE TABLE event_external_links (
  source TEXT NOT NULL,
  external_id TEXT NOT NULL,
  event_id TEXT NOT NULL REFERENCES event_details(content_id),
  source_version INTEGER NOT NULL CHECK(source_version>0),
  request_hash TEXT NOT NULL,
  response_json TEXT NOT NULL CHECK(json_valid(response_json)),
  updated_at TEXT NOT NULL,
  PRIMARY KEY(source,external_id)
);
CREATE INDEX event_external_event_idx ON event_external_links(event_id);
CREATE TABLE integration_requests (
  key_id TEXT NOT NULL,
  idempotency_key TEXT NOT NULL,
  request_hash TEXT NOT NULL,
  status_code INTEGER NOT NULL,
  response_json TEXT NOT NULL CHECK(json_valid(response_json)),
  etag TEXT,
  expires_at TEXT NOT NULL,
  created_at TEXT NOT NULL,
  PRIMARY KEY(key_id,idempotency_key)
);
CREATE TABLE event_unpublish_records (
  id TEXT PRIMARY KEY,
  event_id TEXT NOT NULL REFERENCES event_details(content_id),
  version INTEGER NOT NULL,
  snapshot_json TEXT NOT NULL CHECK(json_valid(snapshot_json)),
  status TEXT NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','complete')),
  created_at TEXT NOT NULL,
  completed_at TEXT,
  UNIQUE(event_id,version)
);
CREATE TABLE event_migration_records (
  event_id TEXT PRIMARY KEY REFERENCES event_details(content_id),
  original_json TEXT NOT NULL CHECK(json_valid(original_json)),
  original_object_key TEXT NOT NULL,
  private_object_key TEXT NOT NULL,
  migrated_at TEXT NOT NULL
);
-- Every mutation starts with a CHECK assertion inside the same D1 batch.
-- Failure rolls back content, revision, mapping, audit and idempotency together.
CREATE TABLE event_write_assertions (id TEXT PRIMARY KEY,passed INTEGER NOT NULL CHECK(passed=1));

